const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const borPoint = ee.Geometry.Point(31.5583, 6.2209); // Bor, South Sudan
  const roi = borPoint.buffer(50000); // 50 km buffer around Bor

  const date2021_start = '2021-11-29'; // 5 days before Dec 4, 2021
  const date2021_end = '2021-12-09';   // 5 days after Dec 4, 2021

  const date2019_start = '2019-12-01'; // 5 days before Dec 6, 2019
  const date2019_end = '2019-12-11';   // 5 days after Dec 6, 2019

  // Sentinel-1 GRD preprocessing function
  function processS1(image) {
    // Select VV polarization and apply speckle filter
    const vv = image.select('VV').focal_median(5); // Median filter as a simple speckle filter
    // Convert to dB
    const db = ee.Image(vv).log10().multiply(10);
    return db.copyProperties(image, ['system:time_start']);
  }

  // Function to calculate water extent
  async function calculateWaterExtent(startDate, endDate, geometry, periodLabel) {
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .map(processS1);

    let colSize = await collection.size().getInfo();
    console.log(`${periodLabel} S1 Images: ${colSize}`);

    if (colSize === 0) {
      console.log(`No Sentinel-1 images found for ${periodLabel}.`);
      return { extent: null, pixelCount: 0, status: 'C1' };
    }

    // Take the median composite of the filtered images
    let composite = collection.median();

    // Water detection using a threshold (typically around -20 dB for open water)
    const waterMask = composite.select('VV').lt(-20); // Values below -20 dB are considered water

    // Calculate the area of water pixels
    // Scale for reduceRegion should be appropriate for Sentinel-1 (10m resolution, use 100 for speed)
    const waterAreaReducer = waterMask.multiply(ee.Image.pixelArea())
                                     .reduceRegion({
                                       reducer: ee.Reducer.sum(),
                                       geometry: geometry,
                                       scale: 100, // Sentinel-1 resolution is ~10m, using 100m for efficiency
                                       maxPixels: 1e10
                                     });

    let waterExtent_m2 = await waterAreaReducer.get('VV').getInfo();

    // Check for calculation failure
    if (waterExtent_m2 === null || isNaN(waterExtent_m2)) {
      console.log(`Calculation failed for ${periodLabel}. Result: ${waterExtent_m2}`);
      return { extent: null, pixelCount: 0, status: 'C3' };
    }

    // Convert to km^2
    let waterExtent_km2 = waterExtent_m2 / 1e6;

    // Validate pixel count (if waterMask itself has no valid pixels, not just no water)
    const pixelCountReducer = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 100,
      maxPixels: 1e10
    });
    const totalPixelsInROI = await pixelCountReducer.get('VV').getInfo();

    if (totalPixelsInROI === 0) {
      console.log(`No valid pixels remaining in ROI after processing for ${periodLabel}.`);
      return { extent: null, pixelCount: 0, status: 'C2' };
    }

    // A zero water extent is a valid result for B, not C2.
    // C2 is for when there are no valid pixels *at all* in the ROI to even perform the calculation.

    console.log(`${periodLabel} Water Extent: ${waterExtent_km2.toFixed(2)} km^2`);
    return { extent: waterExtent_km2, pixelCount: totalPixelsInROI, status: 'OK' };
  }

  // Calculate for 2021
  const result2021 = await calculateWaterExtent(date2021_start, date2021_end, roi, '2021 (Dec 4)');
  if (result2021.status !== 'OK') {
    console.log(result2021.status);
    return;
  }

  // Calculate for 2019
  const result2019 = await calculateWaterExtent(date2019_start, date2019_end, roi, '2019 (Dec 6)');
  if (result2019.status !== 'OK') {
    console.log(result2019.status);
    return;
  }

  // 5. Validation & Final Answer
  if (result2021.extent === null || result2019.extent === null) {
    console.log("C3"); // One of the extents is null, indicating a prior failure
    return;
  }

  // Compare extents
  if (result2021.extent > result2019.extent) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
